sp_widget.script:
(function() { data.preview = { sections: [] }; data.templateId = $sp.getParameter("template_id") || "";
  try { if (!data.templateId) return; var tGr = new GlideRecord("x_1433041_identi_0_template"); if (tGr.get(data.templateId)) { data.preview.name = tGr.getValue("name"); data.preview.description = tGr.getValue("description"); }
    var sGr = new GlideRecord("x_1433041_identi_0_section"); sGr.addQuery("template", data.templateId); sGr.orderBy("order"); sGr.setLimit(50); sGr.query();
    while (sGr.next()) { var section = { name: sGr.getValue("name"), questions: [] }; var qGr = new GlideRecord("x_1433041_identi_0_question"); qGr.addQuery("section", sGr.getValue("sys_id")); qGr.orderBy("order"); qGr.setLimit(100); qGr.query();
      while (qGr.next()) { section.questions.push({ text: qGr.getValue("text"), type: qGr.getDisplayValue("question_type"), mandatory: qGr.getValue("mandatory") === "1" }); } data.preview.sections.push(section); }
  } catch (e) { gs.error("IBAR Template Preview widget error: " + e.message); }
})();
